<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { getAdminActivities, updateActivityStatus, deleteActivity } from '@/api/admin'
import type { Activity } from '@/api/activities'
import { useRoute, useRouter } from 'vue-router'
import AdminSearchPanel from '@/components/AdminSearchPanel.vue'
const router = useRouter(); const route = useRoute(); const records = ref<Activity[]>([]); const loading = ref(true); const total = ref(0); const page = ref(1)
const labels: Record<string, string> = { DRAFT: '草稿', PUBLISHED: '已发布', CLOSED: '已关闭', FINISHED: '已完成', CANCELLED: '已取消' }
async function load(next = page.value) { loading.value = true; page.value = next; try { const { data } = await getAdminActivities({ page: page.value, pageSize: 10, keyword: route.query.keyword, activityType: route.query.type, status: route.query.status }); records.value = data.records; total.value = data.total } finally { loading.value = false } }
onMounted(load); watch(() => route.fullPath, () => load())
async function changeStatus(row: Activity, status: string) { await updateActivityStatus(row.id, status); ElMessage.success('状态已更新'); await load() }
async function remove(row: Activity) { await ElMessageBox.confirm(`确定删除「${row.title}」吗？`, '删除活动'); await deleteActivity(row.id); ElMessage.success('活动已删除'); await load() }
</script>
<template><section class="content"><div class="title"><div><h1>活动管理</h1><p>创建活动、调整状态并维护报名入口。</p></div><div><el-button @click="load()">刷新</el-button><el-button type="primary" @click="router.push('/admin/activities/new')">新增活动</el-button></div></div><AdminSearchPanel /><el-table v-loading="loading" :data="records" stripe><el-table-column prop="title" label="活动名称" min-width="220" /><el-table-column prop="activityType" label="类型" /><el-table-column prop="location" label="地点" /><el-table-column label="时间" min-width="160"><template #default="scope">{{ scope.row.startTime?.replace('T', ' ').slice(0, 16) }}</template></el-table-column><el-table-column label="状态"><template #default="scope"><el-tag>{{ labels[scope.row.status] }}</el-tag></template></el-table-column><el-table-column label="操作" width="360"><template #default="scope"><el-button link @click="router.push(`/admin/activities/${scope.row.id}/edit`)">编辑</el-button><el-button link @click="router.push(`/admin/activities/${scope.row.id}/applications`)">报名名单</el-button><el-button v-if="scope.row.status === 'DRAFT'" type="success" link @click="changeStatus(scope.row as Activity, 'PUBLISHED')">发布</el-button><el-button v-if="scope.row.status === 'PUBLISHED'" type="warning" link @click="changeStatus(scope.row as Activity, 'CLOSED')">关闭</el-button><el-button v-if="['DRAFT', 'CLOSED', 'CANCELLED'].includes(scope.row.status)" type="danger" link @click="remove(scope.row as Activity)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!loading && !records.length" description="暂无活动" /><el-pagination v-if="total > 10" v-model:current-page="page" layout="prev, pager, next" :page-size="10" :total="total" @current-change="load" /></section></template>
<style scoped>.content { padding: 0; }.title { display:flex; justify-content:space-between; align-items:start; margin-bottom:20px; }.title h1 { margin:0; color:var(--df-primary-950); }.title p { margin:8px 0 0; color:#77717e; }.el-pagination { justify-content:center; margin-top:22px; }</style>
